using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace LocTool.App;

/// <summary>
/// WPF Application entry point. Handles startup initialization, EPPlus license configuration,
/// dependency injection setup, and creates the main window.
/// </summary>
partial class App
{
    private readonly IServiceProvider _serviceProvider;

    public App()
    {
        // Build configuration and services during construction
        var configuration = new ConfigurationBuilder()
            .SetBasePath(Directory.GetCurrentDirectory())
            .AddJsonFile("appsettings.json", optional: true, reloadOnChange: true)
            .Build();

        var services = new ServiceCollection();
        services.AddConfiguration(configuration);

        // Register Core services
        // services.AddSingleton<ILocalizationService, LocalizationService>();
        // services.AddSingleton<IExcelService, ExcelService>();

        // Register ViewModels
        // services.AddTransient<MainViewModel>();

        _serviceProvider = services.BuildServiceProvider();
    }

    /// <summary>
    /// Called when the application is starting. Sets EPPlus license context and
    /// creates the main window.
    /// </summary>
    /// <remarks>
    /// IMPORTANT: EPPlus LicenseContext must be set before any EPPlus API calls.
    /// This is required by EPPlus 5+ license terms.
    /// </remarks>
    protected override void OnStartup(StartupEventArgs e)
    {
        base.OnStartup(e);

        // CRITICAL: Set EPPlus license context BEFORE any EPPlus use.
        // This must be done in OnStartup, not in a lazy initialization routine.
        // Skipping this will result in a LicenseException at runtime.
        OfficeOpenXml.ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;

        // TODO: Resolve MainViewModel and create MainWindow
        // var mainViewModel = _serviceProvider.GetRequiredService<MainViewModel>();
        // var mainWindow = new MainWindow { DataContext = mainViewModel };
        // mainWindow.Show();
    }
}
